# Fake Tally XML server for testing flow-sync.ps1 without a real Tally.
# Answers the same request types with canned XML shaped like Tally Prime's output.
param([int]$Port = 9099)
$l = New-Object System.Net.HttpListener
$l.Prefixes.Add("http://localhost:$Port/")
$l.Start()
Write-Host "Mock Tally on http://localhost:$Port/"
$alter = 105
$writes = 0
while ($l.IsListening) {
  $ctx = $l.GetContext()
  $body = (New-Object IO.StreamReader($ctx.Request.InputStream, [Text.Encoding]::UTF8)).ReadToEnd()
  if ($body -match 'Import|Create|Alter') { $writes++ }
  $resp = '<ENVELOPE><BODY><DATA><COLLECTION></COLLECTION></DATA></BODY></ENVELOPE>'
  if ($body -match 'FlowCompanies') {
    $resp = '<ENVELOPE><BODY><DATA><COLLECTION><COMPANY NAME="Flow Sanitation (2024-26)"><STARTINGFROM TYPE="Date">20240401</STARTINGFROM></COMPANY></COLLECTION></DATA></BODY></ENVELOPE>'
  } elseif ($body -match 'FlowDebtors') {
    $resp = @'
<ENVELOPE><BODY><DATA><COLLECTION>
<LEDGER NAME="Gupta Builders"><PARENT>Sundry Debtors</PARENT><CLOSINGBALANCE>-486000.00</CLOSINGBALANCE><PARTYGSTIN>09ABCPG1234K1Z5</PARTYGSTIN><LEDGERMOBILE>98xxxx1101</LEDGERMOBILE><ADDRESS.LIST><ADDRESS>Plot 4, Sector 12</ADDRESS><ADDRESS>Lucknow</ADDRESS></ADDRESS.LIST><LEDSTATENAME>Uttar Pradesh</LEDSTATENAME><CREDITLIMIT>-1000000.00</CREDITLIMIT><BILLCREDITPERIOD>30 Days</BILLCREDITPERIOD></LEDGER>
<LEDGER NAME="Sharma Sanitary Store &amp; Co"><PARENT>Retailers</PARENT><CLOSINGBALANCE>-612000.00</CLOSINGBALANCE><LEDGSTREGDETAILS.LIST><GSTIN>09AAKPS5678L1Z2</GSTIN></LEDGSTREGDETAILS.LIST><CREDITLIMIT>-500000.00</CREDITLIMIT></LEDGER>
<LEDGER NAME="Cash Customer"><PARENT>Sundry Debtors</PARENT><CLOSINGBALANCE>1200.00</CLOSINGBALANCE></LEDGER>
</COLLECTION></DATA></BODY></ENVELOPE>
'@
  } elseif ($body -match 'FlowCreditors') {
    $resp = '<ENVELOPE><BODY><DATA><COLLECTION><LEDGER NAME="Hindware Ltd"><PARENT>Sundry Creditors</PARENT><CLOSINGBALANCE>2840000.00</CLOSINGBALANCE></LEDGER></COLLECTION></DATA></BODY></ENVELOPE>'
  } elseif ($body -match 'FlowItems') {
    $resp = @'
<ENVELOPE><BODY><DATA><COLLECTION>
<STOCKITEM NAME="Racold Storage Geyser 25L"><PARENT>Racold</PARENT><BASEUNITS>Nos</BASEUNITS><CLOSINGBALANCE> 16 Nos</CLOSINGBALANCE><CLOSINGRATE>10,900.00/Nos</CLOSINGRATE><CLOSINGVALUE>-174400.00</CLOSINGVALUE><REORDERBASE> 12 Nos</REORDERBASE></STOCKITEM>
<STOCKITEM NAME="UltraTech Tile Adhesive 20kg"><PARENT>UltraTech BPD</PARENT><CLOSINGBALANCE> 180 Bags</CLOSINGBALANCE><CLOSINGRATE>420.00/Bags</CLOSINGRATE><CLOSINGVALUE>-75600.00</CLOSINGVALUE></STOCKITEM>
</COLLECTION></DATA></BODY></ENVELOPE>
'@
  } elseif ($body -match 'Bills Receivable') {
    $resp = '<ENVELOPE><BILLFIXED><BILLDATE>4-Jul-26</BILLDATE><BILLREF>SI-1890</BILLREF><BILLPARTY>Sharma Sanitary Store &amp; Co</BILLPARTY></BILLFIXED><BILLCL>-412000.00</BILLCL><BILLDUE>3-Aug-26</BILLDUE><BILLOVERDUE>115</BILLOVERDUE><BILLFIXED><BILLDATE>15-Oct-26</BILLDATE><BILLREF>SI-2210</BILLREF><BILLPARTY>Gupta Builders</BILLPARTY></BILLFIXED><BILLCL>-486000.00</BILLCL><BILLDUE>14-Nov-26</BILLDUE><BILLOVERDUE>12</BILLOVERDUE></ENVELOPE>'
  } elseif ($body -match 'FlowVouchers') {
    $after = 0; if ($body -match 'AlterID &gt; (\d+)') { $after = [int]$Matches[1] }
    $v = @()
    if ($after -lt 101) { $v += '<VOUCHER VCHTYPE="Sales Order"><DATE>20261120</DATE><GUID>g-101</GUID><MASTERID>101</MASTERID><ALTERID>101</ALTERID><VOUCHERTYPENAME>Sales Order</VOUCHERTYPENAME><VOUCHERNUMBER>SO-55</VOUCHERNUMBER><PARTYLEDGERNAME>Gupta Builders</PARTYLEDGERNAME><ALLINVENTORYENTRIES.LIST><STOCKITEMNAME>Racold Storage Geyser 25L</STOCKITEMNAME><ACTUALQTY> 8 Nos</ACTUALQTY><BILLEDQTY> 8 Nos</BILLEDQTY><RATE>10900.00/Nos</RATE><AMOUNT>87200.00</AMOUNT><BATCHALLOCATIONS.LIST><GODOWNNAME>Main Location</GODOWNNAME><ORDERNO>SO-55</ORDERNO><ORDERDUEDATE>20261130</ORDERDUEDATE></BATCHALLOCATIONS.LIST></ALLINVENTORYENTRIES.LIST></VOUCHER>' }
    if ($after -lt 102) { $v += '<VOUCHER><DATE>20261122</DATE><GUID>g-102</GUID><MASTERID>102</MASTERID><ALTERID>102</ALTERID><VOUCHERTYPENAME>Delivery Note</VOUCHERTYPENAME><VOUCHERNUMBER>DN-12</VOUCHERNUMBER><PARTYLEDGERNAME>Gupta Builders</PARTYLEDGERNAME><ALLINVENTORYENTRIES.LIST><STOCKITEMNAME>Racold Storage Geyser 25L</STOCKITEMNAME><ACTUALQTY> -4 Nos</ACTUALQTY><AMOUNT>43600.00</AMOUNT><BATCHALLOCATIONS.LIST><ORDERNO>SO-55</ORDERNO></BATCHALLOCATIONS.LIST></ALLINVENTORYENTRIES.LIST></VOUCHER>' }
    if ($after -lt $alter) { $v += "<VOUCHER><DATE>20261126</DATE><GUID>g-103</GUID><MASTERID>103</MASTERID><ALTERID>$alter</ALTERID><VOUCHERTYPENAME>GST Sales</VOUCHERTYPENAME><VOUCHERNUMBER>SI-2401</VOUCHERNUMBER><PARTYLEDGERNAME>Gupta Builders</PARTYLEDGERNAME><AMOUNT>-51448.00</AMOUNT><ALLINVENTORYENTRIES.LIST><STOCKITEMNAME>Racold Storage Geyser 25L</STOCKITEMNAME><ACTUALQTY> 4 Nos</ACTUALQTY><RATE>10900.00/Nos</RATE><AMOUNT>43600.00</AMOUNT><BATCHALLOCATIONS.LIST><ORDERNO>SO-55</ORDERNO></BATCHALLOCATIONS.LIST></ALLINVENTORYENTRIES.LIST></VOUCHER>" }
    $resp = '<ENVELOPE><BODY><DATA><COLLECTION>' + ($v -join '') + '</COLLECTION></DATA></BODY></ENVELOPE>'
    $alter++   # each call simulates an edit in Tally, so the next run picks up one changed voucher
  }
  $bytes = [Text.Encoding]::UTF8.GetBytes($resp)
  $ctx.Response.ContentType = 'text/xml; charset=utf-8'
  $ctx.Response.OutputStream.Write($bytes, 0, $bytes.Length)
  $ctx.Response.Close()
  if ($writes) { Write-Host "WARNING: received $writes write-like request(s)" }
}
